import{_ as o,C as t,o as r,c as s,j as i,E as n,a as d,a3 as e}from"./chunks/framework.C6R8kWFE.js";const x=JSON.parse(`{"title":"4-hafta","description":"","frontmatter":{"title":"4-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"9-sinf (BI)","link":"/9-sinf-bi/"},"n":4,"bob":"II-bob · SQL va relatsion ma’lumotlar tahlili","lessons":[{"g":10,"title":"Relatsion ma'lumotlar bazalari va model tushunchasi (2-qism): Normalizatsiya asoslari va BI'dagi o'rni","lead":"Bitta katta Excel jadval — qulaydek tuyuladi. Lekin mijoz telefonini 50 joyda almashtirish kerak bo'lsa-chi? Bugun ma'lumotni «to'g'ri bo'laklarga ajratish» san'ati — normalizatsiyani o'rganamiz.","link":"/9-sinf-bi/hafta-04/dars-1","slide":"/slaydlar/9-sinf-bi/hafta-04/dars-1.html","test":"/slaydlar/9-sinf-bi/hafta-04/dars-1-test.html"},{"g":11,"title":"Relatsion ma'lumotlar bazalari va model tushunchasi (3-qism): RDBMS muhitlari va ma'lumotlar yaxlitligi","lead":"Excel'da manfiy narx yoki ikki xil bir xil ID ni hech kim to'xtatmaydi. Haqiqiy ma'lumotlar bazasi esa bunday xatoni «yo'q!» deb rad etadi. Bugun bazani himoya qiluvchi qoidalar — cheklovlar bilan tanishamiz.","link":"/9-sinf-bi/hafta-04/dars-2","slide":"/slaydlar/9-sinf-bi/hafta-04/dars-2.html","test":"/slaydlar/9-sinf-bi/hafta-04/dars-2-test.html"},{"g":12,"title":"SQL asoslari: SELECT, ustunlar va sodda ifodalar","lead":"Minglab qatorli jadvaldan kerakli ma'lumotni bir qator kod bilan olish — BI analitigining super kuchi. Bugun SQL ning eng muhim so'zi — SELECT bilan ishlaymiz.","link":"/9-sinf-bi/hafta-04/dars-3","slide":"/slaydlar/9-sinf-bi/hafta-04/dars-3.html","test":"/slaydlar/9-sinf-bi/hafta-04/dars-3-test.html"}],"test":"/slaydlar/9-sinf-bi/hafta-04/hafta-test.html"}},"headers":[],"relativePath":"9-sinf-bi/hafta-04/index.md","filePath":"9-sinf-bi/hafta-04/index.md"}`),h={name:"9-sinf-bi/hafta-04/index.md"},u={class:"blk"},c={id:"uyga-vazifa",tabindex:"-1"};function m(g,a,b,f,v,y){const l=t("Icon");return r(),s("div",null,[i("div",u,[i("h2",c,[n(l,{name:"house"}),a[0]||(a[0]=d(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=e('<p>Mazkur haftada o&#39;tilgan darslar bo&#39;yicha mustaqil bajarish uchun topshiriqlar. Har bir vazifa 20–30 daqiqaga mo&#39;ljallangan.</p><hr><h3 id="_10-dars-normalizatsiya-asoslari-va-bi-dagi-o-rni" tabindex="-1">10-dars: Normalizatsiya asoslari va BI&#39;dagi o&#39;rni <a class="header-anchor" href="#_10-dars-normalizatsiya-asoslari-va-bi-dagi-o-rni" aria-label="Permalink to &quot;10-dars: Normalizatsiya asoslari va BI&#39;dagi o&#39;rni&quot;">​</a></h3><ol><li>Quyidagi «yassi» kutubxona jadvalini oling: <code>KitobID, KitobNomi, Muallif, MuallifDavlati, OquvchiIsmi, OquvchiSinfi, OlinganSana, QaytarishSana</code>.</li><li>Undagi takrorlanuvchi ma&#39;lumotlarni belgilang va har bir anomaliya (Update, Insert, Delete) uchun bittadan misol yozing.</li><li>Jadvalni bosqichma-bosqich 1NF → 2NF → 3NF ga keltiring. Natijada 3–4 ta jadval hosil bo&#39;ladi (masalan: <code>Mualliflar</code>, <code>Kitoblar</code>, <code>Oquvchilar</code>, <code>Ijaralar</code>).</li><li>Sxemani daftarda chizing: har bir jadvalda PK, FK va munosabat turi (1:N, M:N) ko&#39;rsatilsin.</li></ol><p><strong>Kutiladigan natija:</strong> anomaliyalar tahlili va 3NF dagi bog&#39;langan jadvallar sxemasi.</p><hr><h3 id="_11-dars-rdbms-muhitlari-va-ma-lumotlar-yaxlitligi" tabindex="-1">11-dars: RDBMS muhitlari va ma&#39;lumotlar yaxlitligi <a class="header-anchor" href="#_11-dars-rdbms-muhitlari-va-ma-lumotlar-yaxlitligi" aria-label="Permalink to &quot;11-dars: RDBMS muhitlari va ma&#39;lumotlar yaxlitligi&quot;">​</a></h3><ol><li>10-dars uyga vazifasidagi kutubxona modeli uchun SSMS da (yoki SQLite da) <code>Kutubxona</code> bazasini yarating.</li><li>Har bir jadval uchun <code>CREATE TABLE</code> skriptini yozing: PK, kerakli FK, kamida bittadan <code>NOT NULL</code>, <code>UNIQUE</code>, <code>CHECK</code> (masalan, <code>QaytarishSana &gt;= OlinganSana</code>) va <code>DEFAULT</code>.</li><li>Har bir jadvalga 3 tadan to&#39;g&#39;ri yozuv qo&#39;shing (<code>INSERT</code>).</li><li>Har bir cheklov turini buzadigan bittadan <code>INSERT</code> yozing, bajaring va chiqqan xato xabarini 1 jumlada izohlang.</li></ol><p><strong>Kutiladigan natija:</strong> ishlaydigan skript, to&#39;ldirilgan jadvallar va 5 ta izohlangan xato.</p><hr><h3 id="_12-dars-sql-asoslari-—-select-ustunlar-va-sodda-ifodalar" tabindex="-1">12-dars: SQL asoslari — SELECT, ustunlar va sodda ifodalar <a class="header-anchor" href="#_12-dars-sql-asoslari-—-select-ustunlar-va-sodda-ifodalar" aria-label="Permalink to &quot;12-dars: SQL asoslari — SELECT, ustunlar va sodda ifodalar&quot;">​</a></h3><ol><li>Darsdagi <code>Mahsulotlar</code> jadvalini 10 ta mahsulotgacha to&#39;ldiring (yangi <code>INSERT</code> lar).</li><li>Quyidagi 6 ta so&#39;rovni yozing va bajaring: <ul><li>barcha ustunlar;</li><li>nomi va narxi <code>Mahsulot</code> va <code>Narx (so&#39;m)</code> taxalluslari bilan;</li><li>har bir mahsulotning ombor qiymati (<code>Narx * Soni</code>);</li><li>QQS bilan narx (<code>Narx * 1.12</code>);</li><li>takrorsiz kategoriyalar (<code>DISTINCT</code>);</li><li>birinchi 3 ta mahsulot (<code>TOP 3</code>).</li></ul></li><li>Har bir so&#39;rov ostiga natijada nechta qator va ustun chiqqanini hamda 1 ta xulosani yozing.</li></ol><p><strong>Kutiladigan natija:</strong> <code>.sql</code> fayl (yoki daftar) — 6 ta to&#39;g&#39;ri so&#39;rov va natijalar tavsifi.</p><hr>',14))])])}const q=o(h,[["render",m]]);export{x as __pageData,q as default};
